import { getEarningTotalsByRateType } from '~/client';

export const useEarningsTotalsByRateType = defineQuery(() => {
  const { isCanvasser } = useUserRole();

  const { data, error, isLoading, refetch } = useQuery({
    key: () => ['earnings-totals-by-rate-type'],
    query: () => getEarningTotalsByRateType({ composable: '$fetch' }),
    staleTime: 60_000,
    enabled: () => isCanvasser.value,
  });

  return {
    data,
    error,
    isLoading,
    refetch,
  };
});
