<template>
  <div :class="cardClass" class="rounded-xl border p-3 sm:p-4">
    <div :class="labelClass" class="text-xs font-semibold tracking-wide flex items-center gap-1.5">
      <component :is="iconComponent" class="size-3.5" />
      <span>{{ headerLabel }}</span>
    </div>
    <div :class="amountClass" class="text-2xl font-bold mt-1" :data-testid="`earnings-summary-${kindKebab}-total`">
      {{ formatAmount(total) }}
    </div>
    <div class="text-xs text-muted-foreground mt-0.5" :data-testid="`earnings-summary-${kindKebab}-count`">
      {{ count }} {{ count === 1 ? 'earning' : 'earnings' }} · past 30 days
    </div>
  </div>
</template>

<script lang="ts" setup>
import { computed } from 'vue';
import { Star, TrendingUp } from 'lucide-vue-next';
import type { EarningRateType } from '~/client';
import { getRateTypeUi } from '~/constants/earnings/rateType';
import { formatAmount } from '~/utils/amount';

interface Props {
  kind: Extract<EarningRateType, 'bonus' | 'increased_rate'>;
  total: number;
  count: number;
}

const props = defineProps<Props>();

const ui = computed(() => getRateTypeUi(props.kind));
const kindKebab = computed(() => (props.kind === 'bonus' ? 'bonus' : 'increased-rate'));
const headerLabel = computed(() => (props.kind === 'bonus' ? 'BONUS EARNED' : 'INCREASED RATE EARNED'));
const cardClass = computed(() =>
  props.kind === 'bonus' ? 'border-violet-500/35 bg-violet-500/5' : 'border-teal-500/35 bg-teal-500/5'
);
const labelClass = computed(() => ui.value.amountTextClass ?? '');
const amountClass = computed(() => ui.value.amountTextClass ?? '');
const iconComponent = computed(() => (props.kind === 'bonus' ? Star : TrendingUp));
</script>
