<template>
  <div v-if="isLoading" data-testid="earnings-summary-skeleton" class="grid grid-cols-1 sm:grid-cols-2 gap-3">
    <div class="h-24 rounded-xl border border-violet-500/30 bg-violet-500/5 animate-pulse" />
    <div class="h-24 rounded-xl border border-teal-500/30 bg-teal-500/5 animate-pulse" />
  </div>

  <div v-else-if="error" data-testid="earnings-summary-error" class="text-sm text-muted-foreground py-2">
    Couldn't load your bonus summary. The list below is unaffected.
  </div>

  <div v-else-if="hasAny" class="grid grid-cols-1 sm:grid-cols-2 gap-3">
    <EarningsRateTypeSummaryCard
      v-if="bonusCount > 0"
      data-testid="earnings-summary-bonus-card"
      kind="bonus"
      :total="bonusTotal"
      :count="bonusCount"
    />
    <EarningsRateTypeSummaryCard
      v-if="increasedCount > 0"
      data-testid="earnings-summary-increased-rate-card"
      kind="increased_rate"
      :total="increasedTotal"
      :count="increasedCount"
    />
  </div>
</template>

<script lang="ts" setup>
import { computed } from 'vue';
import type { EarningTotalsByRateTypeResponse } from '~/client';
import EarningsRateTypeSummaryCard from './EarningsRateTypeSummaryCard.vue';

interface Props {
  totals: EarningTotalsByRateTypeResponse | null | undefined;
  isLoading: boolean;
  error: unknown;
}

const props = defineProps<Props>();

const bonusTotal = computed(() => Number(props.totals?.bonus.total ?? 0));
const bonusCount = computed(() => props.totals?.bonus.count ?? 0);
const increasedTotal = computed(() => Number(props.totals?.increased_rate.total ?? 0));
const increasedCount = computed(() => props.totals?.increased_rate.count ?? 0);
const hasAny = computed(() => bonusCount.value > 0 || increasedCount.value > 0);
</script>
