<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Earnings" show-doc>
      <div class="flex gap-2">
        <template v-if="isAdminOrManager">
          <NuxtLink :to="{ name: 'earnings-create' }">
            <Button>Create Earning</Button>
          </NuxtLink>
          <NuxtLink :to="{ name: 'earnings-transactions' }">
            <Button variant="outline">Transactions</Button>
          </NuxtLink>
        </template>
        <NuxtLink v-else-if="isCanvasser" :to="{ name: 'earnings-balance' }">
          <Button>My Balance</Button>
        </NuxtLink>
      </div>
    </PageTitle>
    <EarningsRateTypeSummary
      v-if="isCanvasser"
      :totals="rateTypeTotals"
      :is-loading="rateTypeTotalsLoading"
      :error="rateTypeTotalsError"
    />
    <EarningsListFilters :params="params" />
    <Card>
      <CardContent class="!p-0 !md:p-0">
        <AppLoader v-if="isLoading" variant="inline" subject="earnings list" />
        <AppError
          v-else-if="error"
          :error="error"
          title="Failed to load earnings list"
          class="p-4 !mb-4"
          variant="table"
        />
        <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
        <AppEmpty v-else-if="!earnings || earnings.items.length === 0" subject="earnings list" variant="table" />
        <template v-else>
          <EarningsListCanvasserTable v-if="isCanvasser" :list="processedCanvasserEarningsList">
            <template #footer>
              <ResponsiveTableFooter v-if="earnings.total_count > 0" :colspan="4" :cols="4" :cols-sm="4">
                <AppPagination :page="params.page" :size="params.size" :total="earnings.total_count" label="earnings" />
              </ResponsiveTableFooter>
            </template>
          </EarningsListCanvasserTable>
          <EarningsListAdminManagerTable v-else-if="isAdminOrManager" :list="processedAdminManagerEarningsList">
            <template #footer>
              <ResponsiveTableFooter v-if="earnings.total_count > 0" :colspan="6" :cols="4" :cols-sm="4">
                <AppPagination :page="params.page" :size="params.size" :total="earnings.total_count" label="earnings" />
              </ResponsiveTableFooter>
            </template>
          </EarningsListAdminManagerTable>
        </template>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { earningsGuidedEmpty } from '~/constants/guidedEmpty/earnings';
import {
  getEarningList,
  type GetEarningListData,
  type GetEarningListResponse,
  type EarningSortBy,
  type SortType,
  type EarningPaymentStatus,
  type EarningRateType,
  type EarningSource,
  type EarningListItemForCanvasser,
  type EarningListItemForAdmin,
  type EarningListItemForManager,
} from '~/client';

useHead({
  title: 'Earnings',
});

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'earnings',
});

const { isCanvasser, isAdminOrManager } = useUserRole();

const route = useRoute();

const params = computed<GetEarningListData['query']>(() => {
  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as EarningSortBy) || 'created_at',
    sort_type: (route.query.sort_type as SortType) || 'desc',
    search_query: (route.query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<EarningPaymentStatus>(route.query.statuses),
    rate_types: processArrayQueryParameterFromUrl<EarningRateType>(route.query.rate_types),
    sources: processArrayQueryParameterFromUrl<EarningSource>(route.query.sources),
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    project_ids: processArrayQueryParameterFromUrl(route.query.project_ids),
    created_date_from: (route.query.created_date_from as string) || undefined,
    created_date_to: (route.query.created_date_to as string) || undefined,
    final_total_min: route.query.final_total_min ? Number(route.query.final_total_min) : undefined,
    final_total_max: route.query.final_total_max ? Number(route.query.final_total_max) : undefined,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetEarningListData['query'];
});

const {
  data: earnings,
  error,
  isLoading,
} = useQuery({
  key: () => ['earnings-list', JSON.stringify(params.value)],
  query: (): Promise<GetEarningListResponse> => getEarningList({ composable: '$fetch', query: ref(params.value) }),
});

const isEmpty = computed(() => !earnings.value || earnings.value.items.length === 0);

const { guidedContent, showGuided } = useGuidedEmpty(earningsGuidedEmpty, isEmpty);

const {
  data: rateTypeTotals,
  error: rateTypeTotalsError,
  isLoading: rateTypeTotalsLoading,
} = useEarningsTotalsByRateType();

const processedCanvasserEarningsList = computed((): EarningListItemForCanvasser[] => {
  if (isEarningListForCanvasser(earnings.value?.items ?? [])) {
    return earnings.value?.items ?? [];
  } else return [];
});

const processedAdminManagerEarningsList = computed((): (EarningListItemForAdmin | EarningListItemForManager)[] => {
  const items = earnings.value?.items ?? [];
  if (isEarningListForAdminManager(items)) {
    return items;
  } else return [];
});
</script>

<style scoped lang="scss"></style>
